// Entradas: trades del MD STREAM (topic 'trade', copia; no se modifican) · 'tick' (100 ms) · respuestas mysql (msg.exKind) · 'db_error' (catch)
// Salida 1 → mysql (1 query en vuelo).
// Semántica: una fila por segundo (reloj local de recepción) + exchange + market_type, sólo si hubo trades. Sin relleno.
const X = context.get('X', 'memory'), C = X.cfg, now = Date.now();
const out = [null];

function pad(n, w) { return String(n).padStart(w || 2, '0'); }
function dt(t) { const d = new Date(Math.floor(t)); return d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate()) + ' ' + pad(d.getUTCHours()) + ':' + pad(d.getUTCMinutes()) + ':' + pad(d.getUTCSeconds()) + '.' + pad(d.getUTCMilliseconds(), 3); }
function fail(reason) {
    const m = String(reason).slice(0, 200);
    if (m !== X.lastErr || now - X.lastLogAt > 60000) { node.warn('market_ex_1s: ' + m + ' · cola ' + X.q.length + ' filas'); X.lastLogAt = now; }
    X.errors++; X.lastErr = m;
    if (X.inflight && X.inflight.kind === 'insert') { X.q = X.inflight.rows.concat(X.q); if (X.q.length > C.maxQueue) { const ex = X.q.length - C.maxQueue; X.q.splice(0, ex); X.dropped += ex; } }
    X.inflight = null;
    X.backoff = Math.min(C.backoffMax, Math.max(C.backoffMin, X.backoff * 2)); X.nextTry = now + X.backoff;
    node.status({ fill: 'red', shape: 'ring', text: 'error DB: ' + m.slice(0, 40) });
}

// ---------- trade individual ----------
if (msg.topic === 'trade') {
    const t = msg.payload;
    if (!t || C.symbols.indexOf(t.symbol) < 0) return null;
    const ts = t.local_receive_timestamp, sec = Math.floor(ts / 1000), usd = t.price * t.quantity;
    if (!isFinite(ts) || !(t.price > 0) || !isFinite(usd) || usd < 0) { X.stats.bad++; return null; }
    const vk = t.symbol + '|' + t.exchange + '|' + (t.market_type === 'perp' ? 'perp' : 'spot');
    if (sec < X.nextSec) {                              // ese segundo ya se cerró (o es anterior al arranque): no se toca el histórico
        if (sec < X.firstSec) X.stats.preStart++; else { X.stats.late++; X.stats.lateByVenue[vk] = (X.stats.lateByVenue[vk] || 0) + 1; }
        return null;
    }
    let s = X.open.get(sec); if (!s) { s = new Map(); X.open.set(sec, s); }
    let a = s.get(vk);
    if (!a) { a = { symbol: t.symbol, exchange: t.exchange, market: t.market_type === 'perp' ? 'perp' : 'spot', recv: -Infinity, px: 0, exTs: 0, n: 0, buy: 0, sell: 0 }; s.set(vk, a); }
    if (ts >= a.recv) { a.recv = ts; a.px = t.price; a.exTs = Number(t.exchange_timestamp) || ts; }   // último recibido (empate: el último en llegar)
    a.n += t.trade_count || 1;                          // fills reales (Binance perp @aggTrade agrupa fills)
    if (t.side === 'BUY') a.buy += usd; else if (t.side === 'SELL') a.sell += usd;   // lado desconocido: no suma a ninguno
    X.stats.trades++;
    return null;
}

// ---------- respuestas / errores mysql ----------
if (msg.topic === 'db_error' || msg.error) {           // antes que las respuestas: el msg del catch conserva exKind
    if (X.inflight && msg.exBatch === X.inflight.id) fail((msg.error && msg.error.message) || 'error DB');
    return null;
}
if (msg.exKind) {
    if (!X.inflight || msg.exBatch !== X.inflight.id) return null;
    if (msg.exKind === 'schema') {
        const have = {};
        (Array.isArray(msg.payload) ? msg.payload : []).forEach(function (r) { if (r && r.COLUMN_NAME) have[String(r.COLUMN_NAME).toLowerCase()] = 1; });
        X.inflight = null;
        const need = ['ts', 'symbol', 'exchange', 'market', 'last_price', 'last_trade_ts', 'recv_ts', 'trades', 'buy_usd', 'sell_usd'];
        if (!Object.keys(have).length) { fail('tabla ' + C.table + ' no existe (crearla con sql/stage8-market_ex_1s.sql)'); return null; }
        const miss = need.filter(function (c) { return !have[c]; });
        if (miss.length) { fail('faltan columnas en ' + C.table + ': ' + miss.join(', ')); return null; }
        X.schema = true; X.backoff = 0; X.lastErr = '';
        return null;
    }
    X.saved += X.inflight.rows.length; X.lastSavedT = X.inflight.maxT; X.backoff = 0; X.lastErr = '';
    X.inflight = null;
    X.lastFlush = X.q.length >= C.batchMax ? 0 : now;
    return null;
}
if (msg.topic !== 'tick') return null;

// ---------- cierre causal de segundos: [S, S+1000) se cierra recién a S + 1000 + graceMs ----------
while (now >= (X.nextSec + 1) * 1000 + C.graceMs) {
    const sec = X.nextSec, s = X.open.get(sec);
    if (s) {
        s.forEach(function (a) {
            X.q.push([dt(sec * 1000), a.symbol, a.exchange, a.market, a.px, dt(a.exTs), dt(a.recv), a.n, Math.round(a.buy * 1e6) / 1e6, Math.round(a.sell * 1e6) / 1e6]);
            X.stats.rows++;
        });
        X.open.delete(sec);
    }
    X.stats.closedSecs++; X.nextSec++;
}
if (X.q.length > C.maxQueue) { const ex = X.q.length - C.maxQueue; X.q.splice(0, ex); X.dropped += ex; }

// ---------- writer: 1 query en vuelo, lotes ----------
if (X.inflight && now - X.inflight.sentAt > C.timeoutMs) fail('timeout: MariaDB no respondió en ' + (C.timeoutMs / 1000) + ' s');
if (!X.inflight && now >= X.nextTry) {
    if (!X.schema) {
        X.inflight = { id: ++X.seq, kind: 'schema', sentAt: now };
        out[0] = { topic: 'SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ?', payload: [C.table], exKind: 'schema', exBatch: X.inflight.id };
    } else if (X.q.length && (X.q.length >= C.batchMax || now - X.lastFlush >= C.flushMs)) {
        const rows = X.q.splice(0, C.batchMax);
        X.inflight = { id: ++X.seq, kind: 'insert', rows: rows, sentAt: now, maxT: rows[rows.length - 1][0] };
        // una fila por (symbol, exchange, market, ts) cerrada UNA vez; el upsert sólo hace idempotente un reintento con los mismos valores
        out[0] = { topic: 'INSERT INTO ' + C.table + ' (ts, symbol, exchange, market, last_price, last_trade_ts, recv_ts, trades, buy_usd, sell_usd) VALUES ? ' +
            'ON DUPLICATE KEY UPDATE last_price = VALUES(last_price), last_trade_ts = VALUES(last_trade_ts), recv_ts = VALUES(recv_ts), trades = VALUES(trades), buy_usd = VALUES(buy_usd), sell_usd = VALUES(sell_usd)',
            payload: [rows], exKind: 'insert', exBatch: X.inflight.id };
    }
}
global.set('md_ex_1s_stats', { trades: X.stats.trades, rows: X.stats.rows, late: X.stats.late, lateByVenue: X.stats.lateByVenue, preStart: X.stats.preStart, bad: X.stats.bad,
    saved: X.saved, queue: X.q.length, errors: X.errors, dropped: X.dropped, lastErr: X.lastErr, lastSaved: X.lastSavedT }, 'memory');
if (now - (X.lastStatus || 0) > 1000) {
    X.lastStatus = now;
    if (!X.lastErr) node.status({ fill: X.schema ? 'green' : 'grey', shape: 'dot', text: X.saved + ' filas guardadas · cola ' + X.q.length + ' · tardíos ' + X.stats.late });
}
return out[0] ? out : null;

