// ===== AGREGADOR POR VENUE (market_ex_1s): configuración y estado =====
const CFG = {
    symbols: ['ZEC'],       // por ahora sólo ZEC
    graceMs: 500,           // igual que el normalizador de market_1s: el segundo [t, t+1000) se cierra a t + 1000 + 500 ms (reloj local)
    table: 'market_ex_1s',
    batchMax: 500, flushMs: 5000, maxQueue: 36000, timeoutMs: 30000, backoffMin: 5000, backoffMax: 60000
};
const X = {
    cfg: CFG,
    nextSec: Math.floor(Date.now() / 1000) + 1,   // el primer segundo guardado es el primero COMPLETO después del arranque
    firstSec: Math.floor(Date.now() / 1000) + 1,
    open: new Map(),                               // sec → Map(venueKey → acumulador)
    stats: { trades: 0, late: 0, preStart: 0, bad: 0, rows: 0, closedSecs: 0, lateByVenue: {} },
    // writer
    q: [], inflight: null, seq: 0, schema: null, lastFlush: Date.now(), backoff: 0, nextTry: 0,
    saved: 0, errors: 0, dropped: 0, lastErr: '', lastLogAt: 0, lastSavedT: null
};
